      final unclassified = [
        for (final key in allKeys)
          if (!isClassifiedYamlKey(key)) key,
      ]..sort();
      expect(
        unclassified,
        isEmpty,
        reason:
            'Unclassified yaml keys: $unclassified. Every top-level key '
            'the parsers read must be owned by a SharedSetting '
