      final cli = bootCli(
        fake.call,
        sessionName: untouched.id,
        // NO sessionsRetention: the byte-identical legacy boot.
      );
      final run = cli.run();
      await waitForIt(
        () => !cli.isBusy && bootIo.out.toString().contains('ok'),
