      );
      bootIo.sendLine('/exit');
      await run;
      final log = await bootLog();
      expect(log, isNot(contains('[retention]')));
      expect(
        (await env.readTextFile(untouched.path)).valueOrNull,
        before,
      );
      expect((await repo.list()).map((m) => m.id), contains(untouched.id));
    });
  });

