{"newText":"  Future<_SessionHeaderFacts?> _headerFacts(String path) async {
    final lines = (await _fs.readTextLines(path, maxLines: 1)).valueOrNull;
    final line = (lines == null || lines.isEmpty) ? null : lines.first;
    if (line == null || line.isEmpty) return null;
    Object? decoded;
    try {
      decoded = jsonDecode(line);
    } on Object {
      return null;
    }
    if (decoded is! Map<String, dynamic>) return null;
    final id = decoded['id'];
    final cwd = decoded['cwd'];
    final timestamp = decoded['timestamp'];
    if (id is! String || cwd is! String || timestamp is! String) return null;
    // The header is untrusted input: a corrupted, truncated, or planted
    // file must not steer a recursive spill delete outside any root.
    // An unsafe cwd disqualifies the unit entirely (fail closed) — the
    // same guard covers the usage walk and the sweep's removeTree.
    if (!isSafeSpillCwd(cwd)) return null;
    final createdAt = DateTime.tryParse(timestamp);
    if (createdAt == null) return null;
    return _SessionHeaderFacts(id: id, cwd: cwd, createdAt: createdAt);
