/// Whether [cwd] from a session header is safe to measure/delete spills
/// under: non-empty, ABSOLUTE, and free of `.`/`..` segments (both
/// separators). Header data is untrusted (a corrupted or planted header
/// must not steer a recursive delete outside any root).
bool isSafeSpillCwd(String? cwd) {
 if (cwd == null || cwd.isEmpty) return false;
 if (!cwd.startsWith('/') && !cwd.startsWith('\\') &&
     !RegExp(r'^[A-Za-z]:[/\\]').hasMatch(cwd)) {
