/// recursive spill `removeTree` outside any root (gh-1746 review).
bool isSafeSpillCwd(String? cwd) {
  if (cwd == null || cwd.isEmpty) return false;
  final isAbsolute =
      cwd.startsWith('/') ||
      cwd.startsWith(r'\') ||
      RegExp(r'^[A-Za-z]:[/\\]').hasMatch(cwd);
