void main() {
  late MemoryExecutionEnv env;
  late JsonlSessionRepo repo;
  late FileSessionPresenceStore presence;
  setUp(() {
    _clockNow = DateTime(2026, 1, 10, 12);
    env = MemoryExecutionEnv(cwd: '/work');
    repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    presence = FileSessionPresenceStore(env: env, root: '/sessions', now: _clock);
  });
  test('debug blockers', () async {
    Future<String> seed({String? name, DateTime? createdAt, DateTime? lastUsed, int sizeBytes = 0}) async {
      final s = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      if (sizeBytes > 0) await s.appendMessage(UserMessage.text('x' * sizeBytes));
      if (name != null) await s.appendSessionName(name);
      final m = await s.getMetadata();
      final created = createdAt ?? _clockNow;
      if (createdAt != null) {
        final raw = (await env.readTextFile(m.path)).valueOrNull!;
        await env.writeFile(m.path, raw.replaceFirst(RegExp(r'"timestamp":"[^"]+"'), '"timestamp":"${createdAt.toIso8601String()}"'));
      }
      env.setMtime(m.path, (lastUsed ?? created).millisecondsSinceEpoch);
      return m.id;
    }
    final giant = await seed(createdAt: daysAgo(90), sizeBytes: 900, lastUsed: daysAgo(0));
    for (var i = 0; i < 3; i++) {
      await seed(createdAt: daysAgo(90), sizeBytes: 10, lastUsed: daysAgo(1));
    }
    final deletable = await seed(createdAt: daysAgo(90), sizeBytes: 100, lastUsed: daysAgo(80));
    await presence.register(giant);
    final swp = SessionRetentionSweeper(fs: env, sessionsRoot: '/sessions', presenceStore: presence, now: _clock);
    final usage = await swp.usage();
    for (final s in usage.sessions) {
      print('${s.sessionId.substring(0,8)} bytes=${s.bytes} spill=${s.spillBytes}');
    }
    print('total=${usage.totalBytes}');
    final cap = usage.totalBytes - 400;
    print('cap=$cap');
    final report = await swp(retention: SessionRetentionConfig(maxTotalBytes: cap, minAgeDays: 0)).sweep(dryRun: false);
    print('deletions=${report.deletions.map((d) => '${d.sessionId.substring(0,8)}:${d.bytes}')}');
    print('blockers=${report.blockers.map((b) => '${b.sessionId.substring(0,8)}:${b.bytes}:${b.exemption}')}');
    print('remaining=${report.remainingBytes} overflow=${report.remainingBytes - cap}');
  });
}
