  'createdAt': m.createdAt.toIso8601String(),
  'lastUpdatedAt': (m.lastUpdatedAt ?? m.createdAt).toIso8601String(),
  'agent': m.metadata?['agent'],
  'parent': subagentParentId(m),
};

